import os
import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

convt3d_decl = r"""
#include <torch/extension.h>
torch::Tensor convt3d48_k3_forward(torch::Tensor x,
                               torch::Tensor w,
                               c10::optional<torch::Tensor> b);
"""

convt3d_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <c10/cuda/CUDAException.h>
#include <cute/tensor.hpp>
using namespace cute;
// ConvTranspose3d (stride=1, pad=0, output_padding=0, groups=1, kernel 3x3x3, C_in=48, C_out=48).
// Each CTA owns a 4x4x4 output tile, stages the 6x6x6 (halo=2) input tile for all 48
// input channels in shared memory, then loops over the 48 input channels accumulating
// into all 48 output channels. 256 threads = 64 spatial positions x 4 groups of 12 oc.
__global__ void convt3d48_k3_kernel(
    const float* __restrict__ X,
    const float* __restrict__ W,
    const float* __restrict__ B,
    float* __restrict__ Y,
    const int Din, const int Hin, const int Win,
    const int Dout, const int Hout, const int Wout)
{
  constexpr int CIN  = 48;
  constexpr int COUT = 48;
  constexpr int TILE = 4;
  constexpr int HALO = 2;
  __shared__ float sX_raw[CIN * 6 * 6 * 6];
  __shared__ float sW_raw[COUT * 27];
  Tensor sX = make_tensor(
      make_smem_ptr(sX_raw),
      make_shape(Int<CIN>{}, Int<6>{}, Int<6>{}, Int<6>{}));
  Tensor sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Int<COUT>{}, Int<27>{}));
  const int n   = blockIdx.y;
  const int tid = threadIdx.x;
  const int tw = (Wout + TILE - 1) / TILE;
  const int th = (Hout + TILE - 1) / TILE;
  int t = blockIdx.x;
  const int tx = t % tw;  t /= tw;
  const int ty = t % th;
  const int tz = t / th;
  const int od0 = tz * TILE;
  const int oh0 = ty * TILE;
  const int ow0 = tx * TILE;
  Tensor gX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * CIN * Din * Hin * Win),
      make_shape(Int<CIN>{}, Din, Hin, Win),
      make_stride(Din * Hin * Win, Hin * Win, Win, Int<1>{}));
  Tensor gY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * COUT * Dout * Hout * Wout),
      make_shape(Int<COUT>{}, Dout, Hout, Wout),
      make_stride(Dout * Hout * Wout, Hout * Wout, Wout, Int<1>{}));
  Tensor gW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Int<CIN>{}, Int<COUT>{}, Int<3>{}, Int<3>{}, Int<3>{}),
      make_stride(Int<COUT * 27>{}, Int<27>{}, Int<9>{}, Int<3>{}, Int<1>{}));
  // Cooperative load of 6x6x6 halo tile for all 48 input channels (zero fill OOB).
  for (int idx = tid; idx < CIN * 216; idx += blockDim.x) {
    const int ic = idx / 216;
    const int q  = idx - ic * 216;
    const int a  = q / 36;
    const int r  = q - a * 36;
    const int b  = r / 6;
    const int c  = r - b * 6;
    const int gd = od0 - HALO + a;
    const int gh = oh0 - HALO + b;
    const int gw = ow0 - HALO + c;
    float v = 0.0f;
    if (gd >= 0 && gd < Din && gh >= 0 && gh < Hin && gw >= 0 && gw < Win) {
      v = gX(ic, gd, gh, gw);
    }
    sX(ic, a, b, c) = v;
  }
  __syncthreads();
  const int sp  = tid & 63;   // 4x4x4 spatial position
  const int grp = tid >> 6;   // 4 groups of 12 output channels
  const int ocb = grp * 12;
  const int ld = sp >> 4;
  const int lh = (sp >> 2) & 3;
  const int lw = sp & 3;
  const int od = od0 + ld;
  const int oh = oh0 + lh;
  const int ow = ow0 + lw;
  const bool valid = (od < Dout) && (oh < Hout) && (ow < Wout);
  float acc[12];
#pragma unroll
  for (int i = 0; i < 12; ++i) {
    const int oc = ocb + i;
    acc[i] = (B != nullptr) ? B[oc] : 0.0f;
  }
  for (int ic = 0; ic < CIN; ++ic) {
    for (int idx = tid; idx < COUT * 27; idx += blockDim.x) {
      const int oc  = idx / 27;
      const int tap = idx - oc * 27;
      const int kd  = tap / 9;
      const int kh  = (tap / 3) % 3;
      const int kw  = tap % 3;
      sW(oc, tap) = gW(ic, oc, kd, kh, kw);
    }
    __syncthreads();
#pragma unroll
    for (int i = 0; i < 12; ++i) {
      const int oc = ocb + i;
      float sum = 0.0f;
#pragma unroll
      for (int tap = 0; tap < 27; ++tap) {
        const int kd = tap / 9;
        const int kh = (tap / 3) % 3;
        const int kw = tap % 3;
        const int sd = ld + HALO - kd;
        const int sh = lh + HALO - kh;
        const int sw = lw + HALO - kw;
        sum += sX(ic, sd, sh, sw) * sW(oc, tap);
      }
      acc[i] += sum;
    }
    // Prevent the next ic iteration from overwriting sW while others still read it.
    __syncthreads();
  }
#pragma unroll
  for (int i = 0; i < 12; ++i) {
    if (valid) {
      const int oc = ocb + i;
      gY(oc, od, oh, ow) = acc[i];
    }
  }
}
torch::Tensor convt3d48_k3_forward(torch::Tensor x,
                                   torch::Tensor w,
                                   c10::optional<torch::Tensor> b)
{
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x/w must be CUDA");
  TORCH_CHECK(x.dim() == 5 && w.dim() == 5, "x/w must be 5D");
  TORCH_CHECK(x.scalar_type() == at::kFloat && w.scalar_type() == at::kFloat, "float32 only");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  const int64_t N   = x_c.size(0);
  const int64_t Din = x_c.size(2);
  const int64_t Hin = x_c.size(3);
  const int64_t Win = x_c.size(4);
  TORCH_CHECK(x_c.size(1) == 48, "Cin must be 48");
  TORCH_CHECK(w_c.size(0) == 48 && w_c.size(1) == 48, "weight must be [48,48,3,3,3]");
  TORCH_CHECK(w_c.size(2) == 3 && w_c.size(3) == 3 && w_c.size(4) == 3, "kernel must be 3x3x3");
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == 48, "bias must be [48]");
    b_ptr = b_c.data_ptr<float>();
  }
  const int64_t Dout = Din + 2;
  const int64_t Hout = Hin + 2;
  const int64_t Wout = Win + 2;
  auto y = torch::empty({N, 48, Dout, Hout, Wout}, x_c.options());
  const int64_t td = (Dout + 3) / 4;
  const int64_t th = (Hout + 3) / 4;
  const int64_t tw = (Wout + 3) / 4;
  dim3 block(256);
  dim3 grid((unsigned)(td * th * tw), (unsigned)N);
  auto stream = c10::cuda::getCurrentCUDAStream();
  convt3d48_k3_kernel<<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)Din, (int)Hin, (int)Win,
      (int)Dout, (int)Hout, (int)Wout);
  C10_CUDA_KERNEL_LAUNCH_CHECK();
  return y;
}
"""
def _find_cutlass_include():
    """Locate (or provision) a CUTLASS checkout that provides cute/tensor.hpp."""
    cands = []
    env = os.environ.get("CUTLASS_PATH") or os.environ.get("CUTLASS_DIR")
    if env:
        cands += [os.path.join(env, "include"), env]
    # CUTLASS headers bundled with an installed PyTorch (third_party/cutlass).
    try:
        tdir = os.path.dirname(torch.__file__)
        cands += [os.path.join(tdir, "include"),
                  os.path.join(tdir, "include", "cutlass", "include"),
                  os.path.join(tdir, "_inductor", "cutlass", "include")]
    except Exception:
        pass
    try:
        import cutlass
        p = os.path.dirname(cutlass.__file__)
        cands += [p, os.path.join(p, "include"),
                  os.path.join(os.path.dirname(p), "cutlass", "include")]
    except Exception:
        pass
    cands += ["/usr/local/cutlass/include", "/opt/cutlass/include",
              os.path.expanduser("~/cutlass/include")]
    for c in cands:
        if c and os.path.exists(os.path.join(c, "cute", "tensor.hpp")):
            return c
    # Last resort: provision a shallow CUTLASS clone into a writable cache dir.
    cache = os.environ.get("CUTLASS_CACHE") or os.path.join(
        os.path.expanduser("~"), ".cache", "cutlass")
    inc = os.path.join(cache, "include")
    if os.path.exists(os.path.join(inc, "cute", "tensor.hpp")):
        return inc
    try:
        import subprocess
        os.makedirs(os.path.dirname(cache), exist_ok=True)
        subprocess.check_call(
            ["git", "clone", "--depth", "1",
             "https://github.com/NVIDIA/cutlass.git", cache])
        if os.path.exists(os.path.join(inc, "cute", "tensor.hpp")):
            return inc
    except Exception:
        pass
    return None
_CUTLASS_INC = _find_cutlass_include()
if _CUTLASS_INC is None:
    raise RuntimeError(
        "CUTLASS/CuTe headers not found and could not be provisioned. Set "
        "CUTLASS_PATH to a cutlass checkout (needs <root>/include/cute/tensor.hpp), "
        "or ensure network access so a shallow clone can be fetched."
    )
_convt3d_mod = None
def _get_convt3d():
    global _convt3d_mod
    if _convt3d_mod is None:
        _convt3d_mod = load_inline(
            name="convt3d48_k3_cute",
            cpp_sources=convt3d_decl,
            cuda_sources=convt3d_src,
            functions=["convt3d48_k3_forward"],
            extra_include_paths=[_CUTLASS_INC],
            extra_cuda_cflags=["-O3", "-std=c++17", "--expt-relaxed-constexpr", "--expt-extended-lambda"],
            verbose=True,
        )
    return _convt3d_mod
class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        assert in_channels == 48 and out_channels == 48 and kernel_size == 3
        assert stride == 1 and padding == 0 and output_padding == 0 and groups == 1
        self.conv_transpose3d = nn.ConvTranspose3d(in_channels, out_channels, kernel_size=(kernel_size, kernel_size, kernel_size), stride=stride, padding=padding, output_padding=output_padding, groups=groups, bias=bias)
        self._mod = _get_convt3d()
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._mod.convt3d48_k3_forward(x, self.conv_transpose3d.weight, self.conv_transpose3d.bias)

