#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// ConvTranspose3d (stride=1, pad=0, output_padding=0, groups=1, kernel 3x3x3, C_in=48, C_out=48.
// This exploits the fact that a 3x3x3 transposed convolution with stride 1 and zero padding is exactly a
// "full" correlation over spatial coordinates; we implement it as a cooperative tiled kernel in CuTe.
// Each CTA:
//   - owns a 4x4x4 spatial output tile,
//   - stages the corresponding 6x6x6 input tile (with halo) in shared memory for all 48 input channels,
//   - loops over the 48 input channels and reuses the staged tile and per-input-channel weights to produce all 48 output channels.
__global__ void convt3d48_k3_kernel(
    const float* __restrict__ X,
    const float* __restrict__ W,
    const float* __restrict__ B,
    float* __restrict__ Y,
    const int Din, const int Hin, const int Win,
    const int Dout, const int Hout, const int Wout)
{
  constexpr int CIN   = 48;
  constexpr int COUT  = 48;
  constexpr int TILE  = 4;
  constexpr int HALO  = 2;
  constexpr int SREG  = TILE + 2 * HALO; // 6
  constexpr int TAP_K = 27;

