  __shared__ float sX_raw[CIN * 6 * 6 * 6 * 6];
  __shared__ float sW_raw[COUT * 27];

  Tensor sX = make_tensor(
      make_smem_ptr(sX_raw),
      make_shape(Int<CIN>{}, Int<6>{}, Int<6>{}, Int<6>{});
  Tensor sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Int<COUT>{}, Int<27>{});

  const int n = blockIdx.y;
  const int tid = threadIdx.x;

  const int tw = (Wout + TILE - 1) / TILE;
  const int th = (Hout + TILE - 1) / TILE;
  const int th2 = (Hout + TILE - 1) / TILE;

  // Decode 3D tile coord from blockIdx.x
  int t = blockIdx.x;
  const int tx = t % tw;  t /= tw;
  const int ty = t % th2;
  const int tz = t / th2;

  const int ow0 = tx * TILE;
  const int oh0 = ty * TILE;
  const int od0 = tz * TILE;

  // Global tensors (CuTe views) for this image.
  // Layouts are standard contiguous NCDHW with weight stored as [Cin, Cout, 3, 3, 3, 3] for this kernel.
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * 48 * Din * Hin * Win,
      make_shape(Int<48>{}, Din, Hin, Win),
      make_stride(Hin * Win, Win, Int<1>{}); // (ic, d, h, w) is not fully expanded here to keep compilation simple; use explicit strides below.
  // The above is just a placeholder for shape clarity. Define the true views:
  Tensor gX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * 48 * Din * Hin * Win,
      make_shape(Int<48>{}, Din, Hin, Win),
      make_stride(Din * Hin * Win, Hin * Win, Win, Int<1>{});

  Tensor gY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * 48 * Dout * Hout * Wout,
      make_shape(Int<48>{}, Dout, Hout, Wout),
      make_stride(Dout * Hout * Wout, Hout * Wout, Wout, Int<1>{});

  Tensor gW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Int<48>{}, Int<48>{}, Int<3>{}, Int<3>{}, Int<3>{}, Int<3>{}),
      make_stride(Int<48 * 27>{}, Int<27>{}, Int<9>{}, Int<3>{}, Int<1>{});

  const float* bias = B;
  float acc[12];

  // Block has 256 threads = 64 spatial positions * 4 output-channel groups (12 channels each).
  const int sp   = tid & 63;   // 4x4x4 spatial position
  const int grp  = tid >> 6;   // 4 groups of 12 output channels
  const int oc0  = grp * 12;

  const int ld = sp >> 4;
  const int lh = (sp >> 2) & 3;
  const int lw = sp & 3;

  const int od = od0 + ld;
  const int oh = oh0 + lh;
  const int ow = ow0 + lw;
  const bool valid = (od < Dout) && (oh < Hout) && (ow < Wout);

  #pragma unroll
  for (int i = 0; i < 12; ++i) {
    const int oc = oc0 + i;
    acc[i] = (bias != nullptr) ? bias[oc] : 0.0f;
  }

  const int id_base = od0 - HALO;
  const int ih_base = oh0 - HALO;
  const int ih_base_w = ow0 - HALO;

  // Load 6x6x6x48 input tile (halo included) with zero fill
  for (int idx = tid; idx < CIN * 6 * 6 * 6; idx += blockDim.x) {
    int r = idx;
    const int ic = r / (6 * 6 * 6); // 0..47
    r -= ic * (6 * 6 * 6);

