    int rem = r - ic * 36 * 0;

    // Recompute robust decomposition below
    int q = idx - ic * (6 * 6 * 6);
    int a = q / 36;
    int rem = q - a * 36;
    int b = rem / 6;
    int c = rem - b * 6 - a * 36;

    const int gd = od0 - HALO + a;
    const int gh = ih_base + b;   // oh0 - 2 + b
    const int gw = ih_base_w + c;  // ow0 - 2 + c

    float v = 0.0f;
