      const int kd = (tap / 9) % 3;
      const int kh = (tap / 3) % 3;
      const int kw = tap % 3;
      // Correct W mapping explicitly in C++ below using direct pointer.
      const int kd = tap / 9;
      const int kh = (tap / 3) % 3;
      const int kw = tap % 3;
      sW(oc, tap) = gW(ic, oc, kd, kh, kw);
    }
  }

  return;
}

